CREATE TABLE users (
  id INT PRIMARY KEY AUTO_INCREMENT,
  name VARCHAR(100),
  email VARCHAR(100) UNIQUE
);

SELECT * FROM users
ORDER BY name ASC
LIMIT 10;

SELECT orders.id, users.name
FROM orders
INNER JOIN users ON orders.user_id = users.id;

SELECT users.name, orders.id
FROM users
LEFT JOIN orders ON users.id = orders.user_id;

SELECT user_id, COUNT(*) AS order_count
FROM orders
GROUP BY user_id;

UPDATE users
SET email = 'new@example.com'
WHERE id = 1;

SELECT avg_total.user_id, avg_total.avg
FROM (
  SELECT user_id, AVG(total) AS avg
  FROM orders
  GROUP BY user_id
) AS avg_total;
